"use client";

import React, { useState } from "react";
import { Plus, ShieldCheck } from "lucide-react";

export function CartCrossSellPanel() {
  const [added, setAdded] = useState(false);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-4 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <h5 className="text-[10px] font-extrabold uppercase text-muted-foreground/60 tracking-wider mb-3">Often Bought Together</h5>

      <div className="p-3 rounded-xl bg-white/[0.02] border border-white/[0.03] flex items-center justify-between gap-3 text-xs">
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 bg-secondary/30 rounded-lg flex items-center justify-center border border-white/[0.04]">
            <ShieldCheck className="w-5 h-5 text-violet-400" />
          </div>
          <div>
            <p className="font-bold">Extended 1Yr Warranty</p>
            <span className="block text-[10px] text-violet-400 font-bold">$19.00</span>
          </div>
        </div>
        <button 
          onClick={() => setAdded(!added)}
          className={`p-1.5 rounded-lg border transition-all ${
            added ? "bg-emerald-600 border-transparent text-white" : "bg-secondary border-border hover:bg-secondary/60 text-foreground"
          }`}
        >
          {added ? <ShieldCheck className="w-3.5 h-3.5" /> : <Plus className="w-3.5 h-3.5" />}
        </button>
      </div>
    </div>
  );
}
